CREATE DATABASE IF NOT EXISTS lost_found CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE lost_found;
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, nama VARCHAR(100) NOT NULL, email VARCHAR(100) NOT NULL UNIQUE, no_hp VARCHAR(20) NOT NULL, password VARCHAR(255) NOT NULL, role ENUM('admin','user') NOT NULL DEFAULT 'user', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS kategori (id INT AUTO_INCREMENT PRIMARY KEY, nama VARCHAR(50) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS lokasi (id INT AUTO_INCREMENT PRIMARY KEY, nama VARCHAR(100) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS laporan (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, kategori_id INT NOT NULL, lokasi_id INT NOT NULL, nama_barang VARCHAR(100) NOT NULL, deskripsi TEXT NOT NULL, tanggal_hilang DATE NOT NULL, foto VARCHAR(255) NULL, status ENUM('menunggu','dipublikasi','ditolak','ditemukan') NOT NULL DEFAULT 'menunggu', catatan_admin VARCHAR(255) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_laporan_user FOREIGN KEY (user_id) REFERENCES users(id), CONSTRAINT fk_laporan_kategori FOREIGN KEY (kategori_id) REFERENCES kategori(id), CONSTRAINT fk_laporan_lokasi FOREIGN KEY (lokasi_id) REFERENCES lokasi(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tanggapan (id INT AUTO_INCREMENT PRIMARY KEY, laporan_id INT NOT NULL, user_id INT NOT NULL, pesan TEXT NOT NULL, kontak VARCHAR(50) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_tanggapan_laporan FOREIGN KEY (laporan_id) REFERENCES laporan(id) ON DELETE CASCADE, CONSTRAINT fk_tanggapan_user FOREIGN KEY (user_id) REFERENCES users(id)) ENGINE=InnoDB;
